  `new_paid_date` date DEFAULT NULL,
  `reason` text,
  `uid` int DEFAULT NULL,
  `shop_id` varchar(255) DEFAULT NULL,
  `log_date` date DEFAULT NULL,
  `log_time` time DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cable_collection_log` (`shop_id`,`log_date`)
